-- C-04 FX revaluation. No historical run, journal or balance rewrite.
set local lock_timeout='5s';set local statement_timeout='60s';
create schema fx_revaluation_private;revoke all on schema fx_revaluation_private from public,anon,authenticated,service_role;grant usage on schema fx_revaluation_private to authenticated;
create function fx_revaluation_private.allowed(resource text,a text) returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select asset_posting_private.allowed(resource,a)$$;
create function fx_revaluation_private.access(a text) returns bigint language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select asset_posting_private.access('accounting:fx-revaluation',a)$$;
create function fx_revaluation_private.history_allowed() returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select fx_revaluation_private.allowed('accounting:fx-revaluation','view') or fx_revaluation_private.allowed('accounting:fx-revaluation-analysis','view')$$;
create function fx_revaluation_private.context_access() returns bigint language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=asset_posting_private.identity();begin if not(fx_revaluation_private.history_allowed()or fx_revaluation_private.allowed('accounting:fx-revaluation','create'))then raise exception using errcode='42501',message='Sin acceso a revaluación.';end if;return sid;end$$;
create function fx_revaluation_private.can_cancel() returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select fx_revaluation_private.allowed('accounting:fx-revaluation','create') and exists(select 1 from public.user_roles ur join public.role_permissions rp using(role_id)join public.permissions p using(permission_id)where ur.user_id=public.app_user_id() and ur.role_id=public.app_active_role_id() and p.code='accounting:journal:reverse')$$;
do $$declare sig text;f record;body text;names text:='fx_assert_access|fx_validate_accounts|fx_save_settings|fx_options|fx_exposures|fx_calculate|fx_prepare|fx_post_journal|fx_execute|fx_cancel|fx_report';begin
 foreach sig in array array['fx_assert_access()','fx_validate_accounts(bigint,bigint)','fx_save_settings(jsonb)','fx_options()','fx_exposures(date,bigint)','fx_calculate(date,bigint,numeric)','fx_prepare(jsonb)','fx_post_journal(bigint,date,integer,text)','fx_execute(jsonb)','fx_cancel(jsonb)','fx_report(jsonb)']loop execute format('alter function public.%s set schema fx_revaluation_private',sig);end loop;
 for f in select p.oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='fx_revaluation_private'and p.proname~'^fx_'loop
  body:=pg_get_functiondef(f.oid);body:=regexp_replace(body,'\mpublic\.('||names||')\s*\(','fx_revaluation_private.\1(','g');body:=regexp_replace(body,'(^|[^[:alnum:]_.])('||names||')\s*\(','\1fx_revaluation_private.\2(','g');execute body;
 end loop;
 -- Fingerprint the same fixed-precision closing rate that is persisted and used on execution.
 body:=pg_get_functiondef('fx_revaluation_private.fx_prepare(jsonb)'::regprocedure);
 if strpos(body,'update fx_revaluation_runs set closing_rate=rate,')=0 then raise exception 'Unexpected FX preview writer';end if;
 body:=replace(body,$n$rate:=coalesce(nullif(p_payload->>'rate','')::numeric,official);$n$,$r$rate:=coalesce(nullif(p_payload->>'rate','')::numeric,official)::numeric(24,10);$r$);
 body:=replace(body,'jsonb_build_array(data,rate,automatic','jsonb_build_array(data,rate::numeric(24,10),automatic');execute body;
end$$;
create or replace function fx_revaluation_private.fx_assert_access() returns bigint language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select asset_posting_private.identity()$$;
create function fx_revaluation_private.run(id bigint,locking boolean default false) returns public.fx_revaluation_runs language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=asset_posting_private.identity();r public.fx_revaluation_runs;begin
 if id is null or id<=0 then raise exception using errcode='22023',message='Proceso inválido.';end if;
 if locking then perform pg_advisory_xact_lock(hashtextextended('fx-subsidiary:'||sid,0));select * into r from public.fx_revaluation_runs where run_id=id and subsidiary_id=sid for update;
 else select * into r from public.fx_revaluation_runs where run_id=id and subsidiary_id=sid;end if;
 if not found then raise exception using errcode='42501',message='Proceso no disponible.';end if;return r;end$$;
create function fx_revaluation_private.currency(cur bigint) returns void language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=asset_posting_private.identity();begin
 if cur is null or not exists(select 1 from public.currencies c join public.subsidiaries s on s.subsidiary_id=sid where c.currency_id=cur and c.currency_id<>s.currency_id and(exists(select 1 from public.subsidiary_currencies sc where sc.subsidiary_id=sid and sc.currency_id=cur)or exists(select 1 from public."transaction"t where t.subsidiary_id=sid and t.currency_id=cur)or exists(select 1 from public.gl_impact g where g.subsidiary_id=sid and g.original_currency_id=cur))) then raise exception using errcode='42501',message='Moneda extranjera no disponible para la filial.';end if;end$$;
create function fx_revaluation_private.validate_run(r public.fx_revaluation_runs) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare item jsonb;k text;v numeric;begin
 perform fx_revaluation_private.currency(r.currency_id);perform fx_revaluation_private.fx_validate_accounts(r.gain_account_id,r.loss_account_id);
 if not asset_posting_private.finite(r.closing_rate)or r.closing_rate<=0 or r.closing_rate>1000000000 then raise exception using errcode='22023',message='La tasa debe ser finita y positiva.';end if;
 if jsonb_typeof(r.snapshot) is distinct from 'array' or r.fingerprint is distinct from md5(jsonb_build_array(r.snapshot,r.closing_rate,r.auto_reverse,r.reversal_date,r.gain_account_id,r.loss_account_id,r.gain_taxable,r.loss_deductible,r.tax_note,r.rate_reason)::text)then raise exception using errcode='55000',message='Regenerar la vista previa: su contenido no coincide con la huella.';end if;
 if not exists(select 1 from public.fiscal_periods p where p.fiscal_period_id=r.fiscal_period_id and p.subsidiary_id=r.subsidiary_id and p.end_date=r.closing_date and not coalesce(p.is_closed,false)and not coalesce(p.gl_closed,false)and not coalesce(p.is_inactive,false))then raise exception using errcode='55000',message='El período de cierre no está disponible.';end if;
 if r.auto_reverse and(r.reversal_date is distinct from r.closing_date+1 or not exists(select 1 from public.fiscal_periods p where p.subsidiary_id=r.subsidiary_id and p.start_date=r.reversal_date and not coalesce(p.is_closed,false)and not coalesce(p.gl_closed,false)and not coalesce(p.is_inactive,false)))then raise exception using errcode='55000',message='El período de reversión no está disponible.';end if;
 for item in select value from jsonb_array_elements(r.snapshot)loop
  if not exists(select 1 from public.chart_accounts a join public.account_subsidiaries s using(account_id)where a.account_id=(item->>'accountId')::bigint and s.subsidiary_id=r.subsidiary_id and s.is_active and not a.is_inactive and a.accepts_entries)then raise exception using errcode='55000',message='Una cuenta de origen dejó de estar habilitada.';end if;
  foreach k in array array['foreignBalance','bookValue','revaluedBalance','adjustment','signedAdjustment']loop v:=(item->>k)::numeric;if not asset_posting_private.finite(v) then raise exception using errcode='22023',message='El detalle contiene importes no finitos.';end if;end loop;
 end loop;
end$$;
create function fx_revaluation_private.check_journal(id bigint,run bigint) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare j public.journal;debits numeric;credits numeric;begin
 select * into j from public.journal where journal_id=id and fx_revaluation_run_id=run and subsidiary_id=asset_posting_private.identity();
 if not found or j.currency_id is distinct from(select currency_id from public.subsidiaries where subsidiary_id=j.subsidiary_id) or j.exchange_rate<>1 or j.status<>'CONTABILIZADO' or not asset_posting_private.finite(j.total_debit)or j.total_debit<=0 or abs(j.total_debit-j.total_credit)>.005 then raise exception using errcode='55000',message='El asiento de revaluación no es coherente.';end if;
 if exists(select 1 from public.journal_line where journal_id=id and(coalesce(debit_fx,0)<>0 or coalesce(credit_fx,0)<>0))or exists(select 1 from public.gl_impact where transaction_id=j.transaction_id and(coalesce(debit_fx,0)<>0 or coalesce(credit_fx,0)<>0))then raise exception using errcode='55000',message='La revaluación no puede modificar saldos en moneda extranjera.';end if;
 select sum(debit_amount),sum(credit_amount) into debits,credits from public.gl_impact where transaction_id=j.transaction_id;
 if not asset_posting_private.finite(debits)or not asset_posting_private.finite(credits)or abs(debits-credits)>.005 or abs(debits-j.total_debit)>.005 then raise exception using errcode='55000',message='El mayor no corresponde al asiento de revaluación.';end if;
end$$;
create function public.fx_options() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=fx_revaluation_private.context_access();result jsonb;can_create boolean:=fx_revaluation_private.allowed('accounting:fx-revaluation','create');begin
 result:=fx_revaluation_private.fx_options()||jsonb_build_object('access',jsonb_build_object('canCreate',can_create,'canViewHistory',fx_revaluation_private.history_allowed(),'canCancel',fx_revaluation_private.can_cancel()));
 if not can_create then result:=result||jsonb_build_object('accounts','[]'::jsonb,'rates','[]'::jsonb,'settings',null);end if;return result;end$$;
create function public.fx_save_settings(p_payload jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin perform fx_revaluation_private.access('create');return fx_revaluation_private.fx_save_settings(p_payload);end$$;
create function public.fx_prepare(p_payload jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=fx_revaluation_private.access('create');rate numeric:=nullif(p_payload->>'rate','')::numeric;result jsonb;r public.fx_revaluation_runs;begin
 perform fx_revaluation_private.currency((p_payload->>'currencyId')::bigint);if rate is not null and(not asset_posting_private.finite(rate)or rate<=0 or rate>1000000000)then raise exception using errcode='22023',message='Tasa inválida.';end if;
 result:=fx_revaluation_private.fx_prepare(p_payload);r:=fx_revaluation_private.run((result->>'run_id')::bigint);perform fx_revaluation_private.validate_run(r);return result;end$$;
create function public.fx_execute(p_payload jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=fx_revaluation_private.access('create');r public.fx_revaluation_runs;result jsonb;begin
 r:=fx_revaluation_private.run((p_payload->>'runId')::bigint,true);perform fx_revaluation_private.validate_run(r);
 if p_payload->>'fingerprint' is distinct from r.fingerprint then raise exception using errcode='55000',message='La vista previa cambió; vuelva a generarla.';end if;
 result:=fx_revaluation_private.fx_execute(p_payload);perform fx_revaluation_private.check_journal((result->>'journal_id')::bigint,r.run_id);if nullif(result->>'reversal_journal_id','')is not null then perform fx_revaluation_private.check_journal((result->>'reversal_journal_id')::bigint,r.run_id);end if;return result;end$$;
create function public.fx_cancel(p_payload jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=fx_revaluation_private.access('create');r public.fx_revaluation_runs;result jsonb;begin
 if not fx_revaluation_private.can_cancel()then raise exception using errcode='42501',message='El rol activo no tiene permiso técnico de anulación.';end if;
 r:=fx_revaluation_private.run((p_payload->>'runId')::bigint,true);perform fx_revaluation_private.validate_run(r);result:=fx_revaluation_private.fx_cancel(p_payload);perform fx_revaluation_private.check_journal((result->>'cancellation_journal_id')::bigint,r.run_id);if nullif(result->>'cancellation_reversal_id','')is not null then perform fx_revaluation_private.check_journal((result->>'cancellation_reversal_id')::bigint,r.run_id);end if;return result;end$$;
create function public.fx_report(p_payload jsonb) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=fx_revaluation_private.context_access();r public.fx_revaluation_runs;result jsonb;begin
 if not fx_revaluation_private.history_allowed()then perform fx_revaluation_private.access('create');r:=fx_revaluation_private.run(nullif(p_payload->>'runId','')::bigint);end if;
 result:=fx_revaluation_private.fx_report(p_payload);
 return jsonb_set(result,'{runs}',coalesce((select jsonb_agg(x||jsonb_build_object('canCancel',fx_revaluation_private.can_cancel() and x->>'status'='CONTABILIZADO' and not exists(select 1 from public.fx_revaluation_runs later where later.subsidiary_id=sid and later.currency_id=(x->>'currency_id')::bigint and later.closing_date>(x->>'closing_date')::date and later.status='CONTABILIZADO')))from jsonb_array_elements(coalesce(result->'runs','[]'::jsonb))x),'[]'::jsonb));end$$;
create function fx_revaluation_private.visible(sid bigint) returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select $1=asset_posting_private.identity() and fx_revaluation_private.history_allowed()$$;
do $$declare t text;p record;c record;begin foreach t in array array['fx_revaluation_settings','fx_revaluation_runs']loop
 execute format('alter table public.%I enable row level security',t);for p in select policyname from pg_policies where schemaname='public'and tablename=t loop execute format('drop policy %I on public.%I',p.policyname,t);end loop;
 execute format('create policy fx_secure_read on public.%I for select to authenticated using(fx_revaluation_private.visible(subsidiary_id))',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
 for c in select column_name from information_schema.columns where table_schema='public'and table_name=t loop execute format('revoke insert(%I),update(%I),select(%I),references(%I)on public.%I from public,anon,authenticated,service_role',c.column_name,c.column_name,c.column_name,c.column_name,t);end loop;execute format('grant select on public.%I to authenticated',t);
 end loop;end$$;
revoke all on all functions in schema fx_revaluation_private from public,anon,authenticated,service_role;grant execute on function fx_revaluation_private.visible(bigint)to authenticated;
revoke all on function public.fx_options(),public.fx_save_settings(jsonb),public.fx_prepare(jsonb),public.fx_execute(jsonb),public.fx_cancel(jsonb),public.fx_report(jsonb)from public,anon,authenticated,service_role;
grant execute on function public.fx_options(),public.fx_save_settings(jsonb),public.fx_prepare(jsonb),public.fx_execute(jsonb),public.fx_cancel(jsonb),public.fx_report(jsonb)to authenticated;
notify pgrst,'reload schema';
